import React, { useEffect, useMemo, useState } from "react";
import api, { mediaUrl } from "../services/api";
import "./header.css";

const CLOSE_ICON =
  "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 18 18'%3E%3Cpath d='M2 2l14 14M16 2L2 16' stroke='%2317224d' stroke-width='2'/%3E%3C/svg%3E";

function linkProps(item) {
  return {
    href: item.url || undefined,
    target: item.openInNewTab ? "_blank" : undefined,
    rel: item.openInNewTab ? "noopener noreferrer" : undefined,
  };
}

export default function Header() {
  const [header, setHeader] = useState(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [coursesOpen, setCoursesOpen] = useState(false);

  useEffect(() => {
    let cancelled = false;

    api
      .get("/header", {
        params: {
          "populate[logo]": true,
          "populate[menuItems][populate]": "children",
        },
      })
      .then((payload) => {
        if (!cancelled) setHeader(payload.data || null);
      })
      .catch(() => {
        if (!cancelled) setHeader(null);
      });

    return () => {
      cancelled = true;
    };
  }, []);

  const menuItems = useMemo(() => header?.menuItems || [], [header]);
  const courseItem = useMemo(
    () => menuItems.find((item) => item.children?.length) || null,
    [menuItems]
  );

  const goTo = (url) => {
    if (!url) return;
    window.location.href = url;
  };

  return (
    <>
      <nav className="navbar navbar-expand-lg header position-fixed">
        <div className="max-width">
          <div className="container-fluid d-flex">
            <div className="d-flex align-items-center">
              <button
                className="navbar-toggler"
                type="button"
                aria-controls="navbarNav"
                aria-expanded={menuOpen}
                aria-label="Toggle navigation"
                onClick={() => setMenuOpen(true)}
              >
                <span className="navbar-toggler-icon" />
              </button>
              <div className="brand-logo">
                <a className="navbar-brand d-flex" href="/">
                  {header?.logoUrl ? (
                    <img className="h-logo" src={header.logoUrl} alt={header.logoAlt || "DocTutorials"} />
                  ) : null}
                </a>
              </div>
            </div>

            {courseItem ? (
              <div className="selector-div custom-select custom-course">
                <div
                  className={`select-selected${coursesOpen ? " select-arrow-active" : ""}`}
                  onClick={() => setCoursesOpen((open) => !open)}
                >
                  {courseItem.label || "Courses"}
                </div>
                <div className={`select-items${coursesOpen ? "" : " select-hide"}`}>
                  {courseItem.children.map((child) => (
                    <div key={child.id || child.url} onClick={() => goTo(child.url)}>
                      {child.label}
                    </div>
                  ))}
                </div>
              </div>
            ) : null}

            {menuOpen ? <div className="menu-backdrop d-lg-none" onClick={() => setMenuOpen(false)} /> : null}

            <div className={`navbar-collapse nav-buttons header-nav${menuOpen ? " show" : ""}`} id="navbarNav">
              <div className="brand-logo collapse-brand">
                <a className="navbar-brand d-flex" href="/">
                  {header?.logoUrl ? (
                    <img className="h-logo" src={header.logoUrl} alt={header.logoAlt || "DocTutorials"} />
                  ) : null}
                </a>
                <img className="closemenu" src={CLOSE_ICON} alt="close-menu" onClick={() => setMenuOpen(false)} />
              </div>

              {header?.loginUrl ? (
                <div className="h-login-signup1">
                  <a className="h-signup-btn btn" {...linkProps({ url: header.loginUrl, openInNewTab: header.loginOpenInNewTab })}>
                    <span className="h-signup">{header.loginLabel || "Go To Dashboard"}</span>
                  </a>
                </div>
              ) : null}

              <ul className="navbar-nav" id="header">
                {menuItems.map((item) => {
                  const hasChildren = item.children?.length > 0;
                  if (!hasChildren) {
                    return (
                      <li key={item.id || item.label} className="nav-item menu-item">
                        <a {...linkProps(item)}>{item.label}</a>
                      </li>
                    );
                  }

                  return (
                    <li key={item.id || item.label} className="nav-item dropdown menu-item">
                      <button type="button" className="dropdown-label">{item.label}</button>
                      <ul className="sub-menu">
                        {item.children.map((child) => (
                          <li key={child.id || child.url} className="dropdown-menu">
                            <a {...linkProps(child)}>{child.label}</a>
                          </li>
                        ))}
                      </ul>
                    </li>
                  );
                })}
              </ul>
            </div>

            {header?.loginUrl ? (
              <div className="d-flex h-login-signup">
                <a {...linkProps({ url: header.loginUrl, openInNewTab: header.loginOpenInNewTab })}>
                  <button className="h-signup-btn btn" type="button">
                    <p className="h-signup">{header.loginLabel || "Login/Signup"}</p>
                  </button>
                </a>
              </div>
            ) : null}
          </div>
        </div>
      </nav>
      <div className="dt-header-offset" />
    </>
  );
}
